class _SyncUserSubscriptionTokens:
    def __init__(self, transport: Transport) -> None:
        self._transport = transport

    def delete(
        self,
        provider: models.SubscriptionProvider,
    ) -> None:
        """Delete Subscription Token

        Delete your subscription token for a provider.

        Your sessions stop billing your subscription immediately, and the
        usage reading goes with it — it described that token's plan.

        Required permissions: delete:user.
        API key: Requires a CLI user token.
        CLI user token: Supported.
        Sandbox token: Not supported by sandbox tokens, even with permissions.ellipsis enabled.
        Higher permission levels include lower levels: read < write < delete.
        """
        path = f"/v1/user/subscription_tokens/{_quote(str(provider))}"
        self._transport.request("DELETE", path, response_model=None)
        return None

    def get(
        self,
        provider: models.SubscriptionProvider,
    ) -> models.SubscriptionToken:
        """Get Subscription Token

        Get one provider's subscription token.

        `configured` is false when nothing is saved. The token itself is
        never returned, only `token_last4`.

        Required permissions: read:user.
        API key: Requires a CLI user token.
        CLI user token: Supported.
        Sandbox token: Not supported by sandbox tokens, even with permissions.ellipsis enabled.
        Higher permission levels include lower levels: read < write < delete.
        """
        path = f"/v1/user/subscription_tokens/{_quote(str(provider))}"
        response = self._transport.request(
            "GET", path, response_model=models.SubscriptionToken
        )
        assert response is not None
        return response

    def list(
        self,
    ) -> models.SubscriptionTokensListResponse:
        """List Subscription Tokens

        List your subscription tokens.

        One entry per supported provider, whether or not you have saved a
        token for it. Tokens are write-only: the response carries only
        `token_last4`, never the token.

        Required permissions: read:user.
        API key: Requires a CLI user token.
        CLI user token: Supported.
        Sandbox token: Not supported by sandbox tokens, even with permissions.ellipsis enabled.
        Higher permission levels include lower levels: read < write < delete.
        """
        path = "/v1/user/subscription_tokens"
        response = self._transport.request(
            "GET", path, response_model=models.SubscriptionTokensListResponse
        )
        assert response is not None
        return response

    def set(
        self,
        provider: models.SubscriptionProvider,
        token: str,
    ) -> models.SubscriptionToken:
        """Set Subscription Token

        Save your subscription token for a provider.

        Replaces whatever was stored. The token is saved DISABLED and
        routes nothing until `POST /v1/user/subscription_tokens/{provider}/verify`
        succeeds. For Claude, use `claude setup-token`. For Codex, paste
        the auth.json credentials from a ChatGPT login. Each subscription
        pays only for models from its corresponding provider.

        Required permissions: write:user.
        API key: Requires a CLI user token.
        CLI user token: Supported.
        Sandbox token: Not supported by sandbox tokens, even with permissions.ellipsis enabled.
        Higher permission levels include lower levels: read < write < delete.
        """
        path = f"/v1/user/subscription_tokens/{_quote(str(provider))}"
        body_fields: dict[str, Any] = {
            "token": token,
        }
        body = build_body(
            models.PutSubscriptionTokenRequest.model_validate(
                {k: v for k, v in body_fields.items() if v is not None}
            )
        )
        response = self._transport.request(
            "POST", path, response_model=models.SubscriptionToken, json_body=body
        )
        assert response is not None
        return response

    def usage(
        self,
        provider: models.SubscriptionProvider,
    ) -> models.SubscriptionUsageResponse:
        """Get Subscription Usage

        Get your plan's last-observed rate-limit windows.

        Display-only, and only as fresh as your last call through Ellipsis
        (`observed_at`) — the same plan used outside Ellipsis moves the
        real windows without us seeing them. Null unless a token is
        enabled for the provider: a disabled token routes nothing, so any
        reading behind it is stale by construction.

        Required permissions: read:user.
        API key: Requires a CLI user token.
        CLI user token: Supported.
        Sandbox token: Not supported by sandbox tokens, even with permissions.ellipsis enabled.
        Higher permission levels include lower levels: read < write < delete.
        """
        path = f"/v1/user/subscription_tokens/{_quote(str(provider))}/usage"
        response = self._transport.request(
            "GET", path, response_model=models.SubscriptionUsageResponse
        )
        assert response is not None
        return response

    def verify(
        self,
        provider: models.SubscriptionProvider,
    ) -> models.VerifySubscriptionTokenResponse:
        """Verify Subscription Token

        Verify the stored token by using it.

        Makes one minimal call on the exact runtime path, so a pass proves
        the token is what will pay. This is the gate on routing: success
        enables the token, failure disables it, so verifying a revoked
        token is how you stop it routing. A 200 with `ok: false` is the
        normal way a bad token is reported — it is an answer, not a
        transport failure.

        Required permissions: write:user.
        API key: Requires a CLI user token.
        CLI user token: Supported.
        Sandbox token: Not supported by sandbox tokens, even with permissions.ellipsis enabled.
        Higher permission levels include lower levels: read < write < delete.
        """
        path = f"/v1/user/subscription_tokens/{_quote(str(provider))}/verify"
        response = self._transport.request(
            "POST", path, response_model=models.VerifySubscriptionTokenResponse
        )
        assert response is not None
        return response


