    async def metrics(
        self,
        handler_id: str,
        *,
        start: Union[datetime, None] = None,
        end: Union[datetime, None] = None,
    ) -> models.HandlerMetricsResponse:
        """Get Handler Metrics

        Return session counts and accumulated spend for a saved handler.

        Filters only by session creation time. Omitted bounds include all
        history. Counts use the current conversation outcome, so an idle
        session remains active. Spend includes the selected sessions' full
        accumulated cost, including activity after the creation-time window.
        Only sessions carrying this exact saved handler id are counted;
        legacy sessions without handler provenance are excluded.

        spend_windows reports current trailing 1-, 7-, and 28-day credit
        debits and effective handler budgets across all attributed sessions.
        Those windows use usage timestamps and are independent of start/end.

        Requires configs:read matching handlers/{service} and unrestricted
        sessions:read. Sandbox tokens with both grants may read metrics.

        Required permissions: read:sessions, read:configs.
        API key: Supported.
        CLI user token: Supported.
        Sandbox token: Requires the ellipsis:api scope and the required grants in the token's permissions.ellipsis configuration.
        Higher permission levels include lower levels: read < write < delete.
        Grant match patterns can further restrict access to individual resources.
        """
        path = f"/v1/handlers/{_quote(handler_id)}/metrics"
        query = build_query(
            {
                "start": start,
                "end": end,
            }
        )
        response = await self._transport.request(
            "GET", path, response_model=models.HandlerMetricsResponse, query=query
        )
        assert response is not None
        return response


